sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
 restrictTasks();

    function restrictTasks() {
        var taskquery = "",
            user = new GlideRecord('sys_user');

        if (user.get(gs.getUserID()) && user.u_associated_business_markets) {
            var markets = user.u_associated_business_markets.toString().split(',');

            taskquery = "trade_id.owning_businessIN" + markets;
            // MSSCUSTODY-6154 - Check if user has access to "GC HK" or "GC UK"
            if (markets.indexOf("GC HK") !== -1)
                taskquery += "^ORtrade_id.other_businessINGC HK";

            if (markets.indexOf("GC UK") !== -1)
                taskquery += "^ORtrade_id.other_businessINGC UK";

        } else {
            //no record should be visible if user has no associated owning business
            taskquery = "trade_id.owning_business=NothingVisible";
        }

        current.addEncodedQuery(taskquery);

    }

})(current, previous);
